{
  "title": "The Mirror's Escape",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The team assembles at the ruined city's edge.",
      "visual_description": "A cracked cobblestone road leads to broken gates draped in faded royal banners. Mara the Cartographer studies a tattered map while the Glass Diver adjusts his helmet, reflecting the distant spires.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp warns of a cursed tower.",
      "visual_description": "The Oracle Lamp flickers on a fallen column, its single eye glowing as it speaks. The Tin Fox stands alert, its blue eyes fixed on a twisted black tower in the distance.",
      "characters": ["oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The Sleeping Tax Collector blocks the gate.",
      "visual_description": "A massive iron gate is barred by the Sleeping Tax Collector, who snores on a pile of stamped papers. His ledger book pillow is covered in old seals.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 4,
      "caption": "The Glass Diver swims through a window to unlock the gate.",
      "visual_description": "The Glass Diver presses his helmet against a grimy window, his reflection rippling as he passes through the glass. Inside, he reaches for a rusty lever.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The gate groans open, revealing the main courtyard.",
      "visual_description": "The iron gate lifts slowly, chains rattling. Beyond, the courtyard is littered with broken statues and torn banners. Mara gestures forward, compass in hand.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Armored patrols march through the square.",
      "visual_description": "A line of empty armor suits clanks across the square, their visors dark. The Tin Fox hides behind a fallen pillar. Mara presses against a wall.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "The Oracle Lamp reveals a hidden passage.",
      "visual_description": "The Oracle Lamp shines its light on a stone wall, where faint runes glow. The Glass Diver touches the wall, and a door slides open.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The team enters the cursed tower's base.",
      "visual_description": "A spiral staircase rises into darkness. Cobwebs hang like curtains. Mara traces her finger on the map, frowning.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The Sleeping Tax Collector is carried along.",
      "visual_description": "The Tin Fox tugs at the Sleeping Tax Collector's sleeve, but he only shifts and mumbles. The team lifts him onto a cart full of old banners.",
      "characters": ["sleeping_tax_collector", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "A magic door of light and shadow blocks the path.",
      "visual_description": "A door made of swirling light and darkness rotates slowly. The Oracle Lamp's flame dims. The Glass Diver steps forward, hand outstretched.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "The Glass Diver shatters the magic door from within.",
      "visual_description": "The Glass Diver dissolves into a reflection on the door's surface, then emerges inside. He pushes outward, and the door cracks into shards of light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "The team climbs the cursed tower.",
      "visual_description": "Stone steps spiral upward, each step covered in old royal seals. Banners of faded gold hang from the walls. Mara notes the path on her map.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "The Sleeping Tax Collector wakes briefly.",
      "visual_description": "The Sleeping Tax Collector opens one eye, yawns, and hands Mara a stamped permit before falling back asleep. The paper reads 'Exit Approved.'",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "The tower top reveals a bridge to freedom.",
      "visual_description": "Through an archway, a long stone bridge stretches over a misty chasm. The far gate is open. Frightened townspeople huddle in doorways nearby.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The team crosses the bridge under watchful eyes.",
      "visual_description": "The bridge is lined with old statues. The Tin Fox scampers ahead, checking for traps. The Glass Diver's helmet glints in the pale sun.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "A patrol of armored suits blocks the far end.",
      "visual_description": "Three empty armor suits line up at the bridge's end, spears raised. The Oracle Lamp flares brightly, blinding them momentarily.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "The Glass Diver distracts the patrols.",
      "visual_description": "The Glass Diver leaps into a puddle on the bridge, emerging on the other side. He taps a shield, and the suits turn to chase his reflection.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 18,
      "caption": "The team escapes through the far gate.",
      "visual_description": "Mara pushes the final gate open. The team rushes through, the Sleeping Tax Collector still asleep on the cart. The ruined city fades behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ],
  "title": "The Mirror's Escape"
}

